/** The documentation's Bot icons: static SVG copies of the app's generated Bot icons, drawn from
 * botIconDesign.ts the way BotIcon.tsx draws them, in tokens.css's dark-theme colours, since
 * a static image cannot read the app's custom properties. */
import fs from "node:fs";
import path from "node:path";
import { buildGeometry, designFor, HEAD, TILE } from "../src/components/Bots/botIconDesign.ts";

export const BOT_ICON_DIRECTORY = "docs/assets/bots";
const marker =
  "<!-- Generated by frontend/scripts/doc-bot-icons.mjs from the app's Bot icon design; run npm run build:docs. -->";

/** The fixed designs, plus profile-drawn examples whose seeds give varied shapes. */
export const BOT_ICONS = [
  ...["chief", "ops", "research", "writer", "engineer", "desk", "checker", "builder"].map(
    (seat) => ({
      file: `${seat}.svg`,
      seed: seat,
      name: seat[0].toUpperCase() + seat.slice(1),
    }),
  ),
  { file: "example-1.svg", seed: "example-bot-66", name: "Example" },
  { file: "example-2.svg", seed: "example-bot-185", name: "Example" },
  // A new Bot can be given pink, one of the two hues no design draws (botHues.ts).
  { file: "example-3.svg", seed: "example-bot-28", name: "Example", hue: "pink" },
];

const GHOST = "var(--or)";
const INK = "var(--on-or)";
const SHAPES = {
  head: { orb: "a tiled sphere", block: "a tiled block", capsule: "a tiled capsule" },
  visor: { pill: "a pill visor", band: "a band visor", round: "a round visor", goggles: "goggles" },
  gear: { none: "", antenna: ", an antenna", twin: ", twin antennas", ear: ", an ear" },
};

/** The custom properties a Bot icon can name: the dark theme block, then the Bot icon block. */
export function iconTokens(css) {
  const tokens = new Map();
  for (const block of [
    /^:root,\s*\[data-theme="dark"\]\s*\{([^}]*)\}/m,
    /^\.bot-icon,\s*\[data-bot-hue\]\s*\{([^}]*)\}/m,
  ]) {
    const body = css.match(block)?.[1];
    if (body === undefined) throw new Error("tokens.css lacks a block the Bot icons read");
    for (const [, name, value] of body.matchAll(/(--[\w-]+)\s*:\s*([^;]+);/g)) {
      tokens.set(name, value.trim());
    }
  }
  return tokens;
}

function xmlText(value) {
  return String(value).replaceAll("&", "&amp;").replaceAll('"', "&quot;").replaceAll("<", "&lt;");
}

function tag(name, attributes, children) {
  const text = Object.entries(attributes)
    .filter(([, value]) => value !== undefined && value !== "")
    .map(([key, value]) => ` ${key}="${xmlText(value)}"`)
    .join("");
  return children === undefined ? `<${name}${text}/>` : `<${name}${text}>${children}</${name}>`;
}

const path_ = (d, attributes = {}) => (d ? tag("path", { d, ...attributes }) : "");
const stops = (list) =>
  list
    .map(([offset, color, opacity]) =>
      tag("stop", { offset, "stop-color": color, "stop-opacity": opacity }),
    )
    .join("");
const highlight = (at, fill) =>
  tag("ellipse", {
    cx: at.cx,
    cy: at.cy,
    rx: at.rx,
    ry: at.ry,
    transform: `rotate(-28 ${at.cx} ${at.cy})`,
    fill,
  });

/** One icon's SVG text, layered as BotIcon.tsx layers it, with every token resolved. */
export function botIconSvg(icon, tokens) {
  const base = designFor(icon.seed, icon.name);
  const design = icon.hue ? { ...base, hue: icon.hue } : base;
  const g = buildGeometry(design);
  const { gear, led } = g;
  const title = design.seat ? icon.name : "An example Bot";
  const description =
    `${design.seat ? `${icon.name}'s` : "A profile-drawn"} Bot icon: ${SHAPES.head[design.head]} ` +
    `with ${SHAPES.visor[design.visor]}${SHAPES.gear[design.gear]}, ${design.eyes} eyes ` +
    `and a ${design.emblem} emblem, lit ${design.hue}.`;
  const lit = path_(g.eyesLit) + path_(g.emblem) + path_(gear.balls);
  const body = [
    tag("title", { id: "title" }, xmlText(title)),
    tag("desc", { id: "desc" }, xmlText(description)),
    tag(
      "defs",
      {},
      [
        tag("clipPath", { id: "head" }, path_(g.head)),
        tag("clipPath", { id: "glass" }, g.visor.map((d) => path_(d)).join("")),
        tag(
          "radialGradient",
          { id: "depth", cx: 0.38, cy: 0.34, r: 0.75 },
          stops([
            [0.45, INK, 0],
            [1, INK, 0.7],
          ]),
        ),
        ...[
          ["shine", 0.32],
          ["glint", 0.9],
          ["bounce", 0.16],
        ].map(([id, opacity]) =>
          tag(
            "radialGradient",
            { id },
            stops([
              [0, GHOST, opacity],
              [1, GHOST, 0],
            ]),
          ),
        ),
        tag(
          "linearGradient",
          { id: "rim", x1: 0, y1: 0, x2: 1, y2: 0 },
          stops([
            [0, GHOST, 0.95],
            [0.6, GHOST, 0.55],
            [0.95, GHOST, 0],
          ]),
        ),
        tag(
          "linearGradient",
          { id: "frame", x1: 0, y1: 0, x2: 0, y2: 1 },
          stops([
            [0, "var(--b-alt)"],
            [1, HEAD],
          ]),
        ),
        tag(
          "linearGradient",
          { id: "edge", x1: 0, y1: 0, x2: 0, y2: 1 },
          stops([
            [0, GHOST, 0.6],
            [0.45, GHOST, 0],
          ]),
        ),
        tag(
          "linearGradient",
          { id: "pane", x1: 0, y1: 0, x2: 0, y2: 1 },
          stops([
            [0, "var(--fill-hi)"],
            [1, INK],
          ]),
        ),
        tag(
          "filter",
          { id: "bloom", x: "-50%", y: "-50%", width: "200%", height: "200%" },
          tag("feGaussianBlur", { stdDeviation: 2.2 }),
        ),
        tag(
          "filter",
          { id: "soft", x: "-20%", y: "-20%", width: "140%", height: "140%" },
          tag("feGaussianBlur", { stdDeviation: 1.1 }),
        ),
      ].join(""),
    ),
    path_(gear.stems, {
      fill: "none",
      stroke: HEAD,
      "stroke-width": 2.6,
      "stroke-linecap": "round",
    }),
    path_(gear.stems, {
      fill: "none",
      stroke: "var(--t3)",
      "stroke-width": 1.3,
      "stroke-linecap": "round",
    }),
    path_(g.head, { fill: HEAD }),
    tag(
      "g",
      { "clip-path": "url(#head)" },
      [
        ...Object.entries(g.tiles).map(([opacity, d]) =>
          path_(d, { fill: TILE, "fill-opacity": opacity }),
        ),
        ...Object.entries(g.glints).map(([opacity, d]) =>
          path_(d, {
            fill: "none",
            stroke: GHOST,
            "stroke-opacity": opacity,
            "stroke-width": 0.4,
            "stroke-linecap": "round",
          }),
        ),
        path_(g.head, { fill: "url(#depth)" }),
        highlight(g.shine, "url(#shine)"),
        highlight(g.glint, "url(#glint)"),
        highlight(g.bounce, "url(#bounce)"),
      ].join(""),
    ),
    path_(g.head, {
      filter: "url(#soft)",
      fill: "none",
      stroke: "url(#rim)",
      "stroke-width": 2.2,
      "stroke-opacity": 0.35,
    }),
    path_(g.head, { fill: "none", stroke: "url(#rim)", "stroke-width": 1.2 }),
    path_(gear.ear, { fill: HEAD, stroke: GHOST, "stroke-opacity": 0.85, "stroke-width": 1.4 }),
    path_(gear.earLight, {
      fill: "none",
      stroke: GHOST,
      "stroke-opacity": 0.6,
      "stroke-width": 0.7,
    }),
    ...Object.entries(g.loose).map(([shade, d]) => path_(d, { fill: shade })),
    path_(g.looseLight, { fill: GHOST, "fill-opacity": 0.28 }),
    tag(
      "g",
      { "clip-path": design.visor === "band" ? "url(#head)" : undefined },
      [
        ...g.frame.map((d) =>
          path_(d, { fill: "url(#frame)", stroke: "url(#edge)", "stroke-width": 0.8 }),
        ),
        ...g.visor.map((d) => path_(d, { fill: "url(#pane)" })),
        tag(
          "g",
          { "clip-path": "url(#glass)" },
          [
            ...g.visor.map((d) =>
              path_(d, {
                filter: "url(#soft)",
                fill: "none",
                stroke: INK,
                "stroke-width": 3.2,
                "stroke-opacity": 0.85,
              }),
            ),
            path_(g.streak, { fill: GHOST, "fill-opacity": 0.08 }),
          ].join(""),
        ),
      ].join(""),
    ),
    path_(g.gloss, {
      fill: "none",
      stroke: GHOST,
      "stroke-opacity": 0.35,
      "stroke-width": 1,
      "stroke-linecap": "round",
    }),
    path_(g.eyesDim, { fill: led, "fill-opacity": 0.12 }),
    tag("g", { filter: "url(#bloom)", fill: led, opacity: 0.85 }, lit),
    tag("g", { fill: led }, lit),
    path_(g.emblemLight, { fill: GHOST, "fill-opacity": 0.42 }),
    path_(g.emblemShade, { fill: INK, "fill-opacity": 0.32 }),
    path_(g.eyesHot + gear.ballsHot, { fill: GHOST, "fill-opacity": 0.62 }),
    ...g.sparks.map((spark) => path_(spark.d, { fill: led, "fill-opacity": spark.opacity })),
  ].join("");
  const svg = tag(
    "svg",
    {
      xmlns: "http://www.w3.org/2000/svg",
      // An intrinsic size keeps the icon small where no stylesheet sizes it, as on GitHub.
      width: 48,
      height: 48,
      viewBox: "4 4 92 92",
      "shape-rendering": "geometricPrecision",
      role: "img",
      "aria-labelledby": "title desc",
    },
    body,
  );
  const resolved = svg.replaceAll(/var\((--[\w-]+)\)/g, (_, name) => {
    const value = tokens.get(name);
    if (value === undefined) throw new Error(`tokens.css has no dark value for ${name}`);
    return value;
  });
  return `${marker}\n${resolved}\n`;
}

/** Every icon file under the repository `root`, keyed by its absolute path. */
export function botIconFiles(root) {
  const tokens = iconTokens(
    fs.readFileSync(path.join(root, "frontend/src/styles/tokens.css"), "utf8"),
  );
  const directory = path.join(root, BOT_ICON_DIRECTORY);
  return new Map(
    BOT_ICONS.map((icon) => [path.join(directory, icon.file), botIconSvg(icon, tokens)]),
  );
}

/** Writes the icons, or with `check` only reports stale or obsolete ones. Files without the
 * generated marker are never replaced or removed. */
export function writeBotIcons(root, files, { check = false } = {}) {
  const directory = path.join(root, BOT_ICON_DIRECTORY);
  const present = fs.existsSync(directory)
    ? fs.readdirSync(directory).map((name) => path.join(directory, name))
    : [];
  const obsolete = present.filter((file) => !files.has(file));
  const stale = [...files].filter(
    ([file, content]) => !fs.existsSync(file) || fs.readFileSync(file, "utf8") !== content,
  );
  if (check) {
    if (obsolete.length || stale.length)
      throw new Error(
        `Bot icons are stale (${stale.length} changed, ${obsolete.length} obsolete); run npm run build:docs`,
      );
    return;
  }
  const generated = (file) => fs.readFileSync(file, "utf8").startsWith(marker);
  for (const file of obsolete) {
    if (!fs.statSync(file).isFile() || !generated(file))
      throw new Error("Refusing to remove an unrecognized Bot icon file");
    fs.unlinkSync(file);
  }
  for (const [file, content] of stale) {
    if (fs.existsSync(file) && !generated(file))
      throw new Error("Refusing to overwrite an unrecognized Bot icon file");
    fs.mkdirSync(directory, { recursive: true });
    fs.writeFileSync(file, content, "utf8");
  }
}
